import{_ as a,c as d,o as n,ae as t}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"Decline EU Withdrawal","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-eu-withdrawal-decline-gql","title":"Decline EU Withdrawal","description":"Declines a declaration when the purchase is exempt from the right of withdrawal. Sets status to declined and clears any prior refund metadata.","query":"mutation DeclineAdminEuWithdrawal($input: declineAdminEuWithdrawalInput!) {\\n  declineAdminEuWithdrawal(input: $input) {\\n    adminEuWithdrawal {\\n      _id\\n      uuid\\n      orderIncrementId\\n      customerEmail\\n      status\\n      declinedAt\\n      declinedReason\\n      declinedByUserId\\n      declinedByName\\n      refundedAt\\n      refundNote\\n      message\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/eu-withdrawals/7\\",\\n    \\"declinedReason\\": \\"Item was a personalised good, exempt from withdrawal.\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"declineAdminEuWithdrawal\\": {\\n      \\"adminEuWithdrawal\\": {\\n        \\"_id\\": 7,\\n        \\"uuid\\": \\"b2f1c0de-5a2e-4d7a-9f2e-3c1a2b4d5e6f\\",\\n        \\"orderIncrementId\\": \\"000000012\\",\\n        \\"customerEmail\\": \\"jane@example.com\\",\\n        \\"status\\": \\"declined\\",\\n        \\"declinedAt\\": \\"2026-07-21T15:00:00+00:00\\",\\n        \\"declinedReason\\": \\"Item was a personalised good, exempt from withdrawal.\\",\\n        \\"declinedByUserId\\": 1,\\n        \\"declinedByName\\": \\"Example Admin\\",\\n        \\"refundedAt\\": null,\\n        \\"refundNote\\": null,\\n        \\"message\\": \\"Withdrawal declined.\\",\\n        \\"updatedAt\\": \\"2026-07-21T15:00:00+00:00\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/eu-withdrawal/mutations/decline.md","filePath":"api/graphql-api/admin/sales/eu-withdrawal/mutations/decline.md"}'),i={name:"api/graphql-api/admin/sales/eu-withdrawal/mutations/decline.md"};function r(o,e,l,c,s,h){return n(),d("div",null,e[0]||(e[0]=[t('<h1 id="decline-eu-withdrawal" tabindex="-1">Decline EU Withdrawal <a class="header-anchor" href="#decline-eu-withdrawal" aria-label="Permalink to &quot;Decline EU Withdrawal&quot;">​</a></h1><p>GraphQL counterpart of <code>POST /api/admin/eu-withdrawals/{id}/decline</code>. Declines a withdrawal declaration when the purchase is exempt from the right of withdrawal (for example a personalised good). Sets <code>status</code> to <code>declined</code> and records who declined it, when, and why. Runs against the admin GraphQL endpoint <code>POST /api/admin/graphql</code>.</p><p><strong>Declining clears any prior refund metadata</strong> (<code>refundedAt</code>, <code>refundedByUserId</code>, <code>refundedByName</code>, <code>refundNote</code>) so the declaration reflects a single current outcome.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><p><code>declineAdminEuWithdrawal</code> — pass the declaration IRI (<code>/api/admin/eu-withdrawals/{id}</code>) as <code>input.id</code>, and the required <code>declinedReason</code>. Select <code>_id</code> for the numeric id on the result.</p><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>ID!</td><td>yes</td><td>The declaration IRI.</td></tr><tr><td><code>declinedReason</code></td><td>String!</td><td>yes</td><td>The reason the declaration is being declined.</td></tr></tbody></table><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.eu_withdrawals.decline</code></p>',9)]))}const m=a(i,[["render",r]]);export{p as __pageData,m as default};
